function pause(){if(state==='play'){state='paused';keys.clear();pressed.clear();panel(`<section class="panel small-panel"><p class="eyebrow">TAKE A BREATHER</p><h2>PAUSED.</h2><p>Chapter 0${levelIndex+1} · ${level.name}<br>Your checkpoint is saved at the start of this chapter.</p><div class="menu-buttons"><button id="resume" class="primary">RESUME →</button><button id="controls" class="secondary">CONTROLS</button><button id="restart" class="secondary">RESTART CHAPTER</button><button id="quit" class="secondary">MAIN MENU</button></div></section>`);bindButton('resume',resume);bindButton('controls',()=>guide(()=>{state='play';pause();}));bindButton('restart',()=>startStage(levelIndex));bindButton('quit',()=>{checkpoint();menu();});}else if(state==='paused')resume();}
function resume(){state='play';panel('');keys.clear();pressed.clear();canvas.focus();}
function gameover(){state='gameover';save.best=Math.max(save.best,score);persist();panel(`<section class="panel small-panel"><p class="eyebrow">THE FIGHT ISN'T OVER</p><h2>CONTINUE?</h2><p>The gang regroups at the start of this chapter. No coins needed.<br>Score ${score.toString().padStart(6,'0')} · Best combo ${bestCombo}</p><div class="menu-buttons"><button id="retry" class="primary">TRY AGAIN →</button><button id="quit" class="secondary">MAIN MENU</button></div></section>`);bindButton('retry',()=>{lives=3;startStage(levelIndex);});bindButton('quit',menu);}
function stageClear(){if(cleared)return;cleared=true;state='clear';score+=2500+Math.floor(player.hp*10);save.unlocked=Math.max(save.unlocked,Math.min(5,levelIndex+1));save.best=Math.max(save.best,score);sfx('clear');save.checkpoint=levelIndex<5?{level:levelIndex+1,hero:selected,difficulty,score,lives}:null;persist();panel(`<section class="panel small-panel"><p class="eyebrow">CHAPTER 0${levelIndex+1} COMPLETE</p><h2>${levelIndex===5?'EDEN IS FREE.':'KEEP THE ENGINE RUNNING.'}</h2><p>${level.end}</p><p style="color:var(--acid)">SCORE ${score.toString().padStart(6,'0')} · BEST COMBO ${bestCombo}</p><div class="menu-buttons"><button id="next" class="primary">${levelIndex===5?'SEE THE ENDING':'NEXT CHAPTER'} →</button></div></section>`);bindButton('next',()=>levelIndex<5?startStage(levelIndex+1):ending());}
function ending(){state='ending';save.checkpoint=null;persist();panel(`<section class="panel small-panel"><p class="eyebrow">LAST EDEN · THE END</p><h2>A WORLD WORTH SAVING.</h2><p>Hannah opens the vault. Jack disconnects the reactor. Mess lifts the fallen gate, and Mustapha leads the rescued animals into the sunrise.</p><p>The Cadillac rolls home carrying four tired heroes, a box of seeds, and one very stubborn baby dinosaur.</p><p style="color:var(--acid)">MUSTAPHA: Same time next adventure?<br>JACK: Only if you're buying the fuel.</p><p>${kills} enemies defeated · ${Math.floor(runTime/60)} minutes · score ${score}<br>All six chapters are now available.</p><div class="menu-buttons"><button id="chapters" class="primary">PLAY A CHAPTER →</button><button id="credits" class="secondary">CREDITS</button><button id="quit" class="secondary">MAIN MENU</button></div></section>`);bindButton('chapters',chapters);bindButton('credits',credits);bindButton('quit',menu);}
function credits(){state='credits';panel(`<section class="panel small-panel"><p class="eyebrow">THANKS FOR PLAYING</p><h2>FOR THE OLD ARCADE DAYS.</h2><p>An unofficial fan sequel created for Mostafa's next adventure. Original character graphics were recovered from the arcade ROM files supplied by the user.</p><p>New story, levels, environments, combat engine, boss behaviors and synthesized soundtrack created for this game. Original Cadillacs and Dinosaurs arcade game and artwork: Capcom. Characters and setting derive from Xenozoic Tales by Mark Schultz.</p><div class="menu-buttons"><button id="quit" class="primary">MAIN MENU →</button></div></section>`);bindButton('quit',menu);}
function spawnEnemy(x,y,type='raider',boss=false){const hp=boss?[210,270,280,330,370,380][levelIndex]:(type==='brute'?76:type==='gunner'?38:type==='raptor'?55:46);const e={id:Math.random(),x,y,z:0,dir:-1,hp:hp*(difficulty==='story'?.8:1.25),maxhp:hp*(difficulty==='story'?.8:1.25),type,boss,phase:1,state:'walk',timer:rand(.5,2),hurt:0,inv:0,anim:rand(0,1),dead:0,attack:0,palette:type==='gunner'?'14':'13',hue:type==='brute'?80:type==='gunner'?15:0};enemies.push(e);return e;}
function spawnWave(n){wave=n;lock={left:Math.max(0,player.x-155),right:Math.min(level.length+240,player.x+570)};const count=difficulty==='story'?3+Math.floor(levelIndex/2):4+Math.floor(levelIndex/2);for(let j=0;j<count;j++){const type=level.drive?'biker':levelIndex>=2&&j===count-1?'raptor':j%3===1?'gunner':j%4===3?'brute':'raider';spawnEnemy(player.x+330+j*46,rand(292,386),type);}toast=level.drive?'CONVOY ESCORT · CLEAR THE ROAD':'AMBUSH · CLEAR THE AREA';toastTime=2.2;}
function spawnBoss(){bossSpawned=true;lock={left:level.length-520,right:level.length+100};const b=spawnEnemy(level.length-100,343,level.kind,true);b.timer=2;toast=level.boss;toastTime=3.5;sfx('special');}
function popup(x,y,text,color='#e9ecd1'){floating.push({x,y,text,color,life:1.15});}
function burst(x,y,color,n=12){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-120,120),vy:rand(-140,60),life:rand(.18,.55),size:rand(2,5),color});}
function damageEnemy(e,amount,knock=0){if(e.dead||e.inv>0)return; e.hp-=amount;e.hurt=e.boss?.08:.21;e.inv=.12;e.x+=knock*(e.boss?.3:1);if(lock)e.x=clamp(e.x,lock.left+20,lock.right-35);if(!e.boss){e.state='hurt';e.timer=.35;}combo++;comboTimer=2.2;bestCombo=Math.max(bestCombo,combo);score+=Math.floor(amount*3);burst(e.x,e.y-48,'#ffe2a1',10);sfx('hit');hitstop=.035;shake=3;
 if(e.hp<=0){if(e.boss&&e.type==='regent'&&e.phase===1){e.phase=2;e.hp=e.maxhp=650*(difficulty==='story'?.8:1.2);e.type='regent';e.state='transform';e.timer=2.7;e.inv=2.7;flash=.75;shake=12;toast='THE PALE REGENT · FINAL FORM';toastTime=4;burst(e.x,e.y-65,'#d5ec69',55);sfx('special');return;} e.dead=.9;e.state='dead';score+=e.boss?1500:250;kills++;burst(e.x,e.y-35,e.boss?'#d5ec69':'#a6ba76',16);if(!e.boss&&Math.random()<.24)drops.push({x:e.x,y:e.y,type:Math.random()<.55?'food':'gun',life:32});}
}
function damagePlayer(amount,fromX,ignoreAir=false){if(player.inv>0||(!ignoreAir&&player.z>28)||player.special>0||player.boost>0)return;player.hp-=amount*(difficulty==='story'?.65:1);player.hurt=.35;player.inv=.95;player.x+=fromX<player.x?15:-15;player.attack=0;combo=0;comboTimer=0;shake=6;flash=.07;sfx('hurt');burst(player.x,player.y-48,'#eea575',8);if(player.hp<=0){lives--;if(lives>0){player.hp=player.maxhp;player.inv=3;player.weapon=null;player.ammo=0;popup(player.x,player.y-95,'BACK IN THE FIGHT','#d5ec69');toast=`${lives} LIVES REMAINING`;toastTime=3;checkpoint();}else gameover();}}
function shoot(x,y,dir,friendly=true,damage=18,speed=620){bullets.push({x,y,z:level.drive?28:48,vx:dir*speed,vy:0,friendly,damage,life:1.5,color:friendly?'#fff4af':'#ef8f68'});}
function attack(){if(player.hurt>0||player.attack>0||player.special>0)return;const h=HEROES[selected];player.attackTotal=level.drive?.17:player.z>8?.38:player.run?.43:.32;player.attack=player.attackTotal;player.comboStep=(player.comboStep+1)%3;sfx(level.drive||player.weapon==='gun'?'gun':'hit');
 if(level.drive||player.weapon==='gun'){shoot(player.x+(level.drive?78:25)*player.dir,player.y,player.dir,true,level.drive?22:32);if(!level.drive&&--player.ammo<=0){player.weapon=null;toast='OUT OF AMMO';toastTime=1.4;}return;}
 if(player.weapon==='bomb'){zones.push({x:player.x+player.dir*145,y:player.y,r:100,t:.55,total:.55,friendly:true,damage:110,air:false});player.weapon=null;player.ammo=0;return;}
 const range=player.weapon==='knife'?94:player.z>8?95:player.run?102:76;const power=h.power*(player.z>8?1.35:player.run?1.4:1)*(player.weapon==='knife'?1.6:1)*(player.comboStep===2?1.15:1);
 for(const e of enemies)if(!e.dead&&Math.abs(e.y-player.y)<38&&Math.abs(e.x-player.x)<range&&Math.sign(e.x-player.x)===player.dir)damageEnemy(e,power,player.dir*(player.comboStep===2?18:6));
 for(const o of objects)if(o.hp>0&&Math.abs(o.y-player.y)<35&&Math.abs(o.x-player.x)<85){o.hp-=power;burst(o.x,o.y-35,'#c3925d',8);if(o.hp<=0){drops.push({x:o.x,y:o.y,type:o.content,life:60});score+=100;sfx('pickup');}}
 if(player.weapon==='knife'&&--player.ammo<=0)player.weapon=null;
}
function jump(){if(player.z>0||player.hurt>0)return;if(level.drive){if(player.boostCd<=0){player.boost=1.15;player.boostCd=3;player.inv=1.2;sfx('jump');}return;}player.vz=355;player.z=.1;sfx('jump');}
function special(){if(player.specialCd>0||player.hurt>0)return;if(!level.drive&&player.hp<12){toast='SPECIAL NEEDS 12 HEALTH';toastTime=1.4;return;}player.special=.65;player.specialCd=2.3;player.inv=.8;if(!level.drive)player.hp=Math.max(1,player.hp-8);sfx('special');shake=7;for(const e of enemies)if(!e.dead&&Math.hypot((e.x-player.x)*.8,e.y-player.y)<150)damageEnemy(e,HEROES[selected].power*2.4,Math.sign(e.x-player.x)*35);for(const o of objects)if(o.hp>0&&Math.abs(o.x-player.x)<125&&Math.abs(o.y-player.y)<75){o.hp=0;drops.push({x:o.x,y:o.y,type:o.content,life:60});}burst(player.x,player.y-40,HEROES[selected].color,24);}
function pickup(){let nearest=null,dist=65;for(const d of drops){const dd=Math.hypot(d.x-player.x,d.y-player.y);if(dd<dist){dist=dd;nearest=d;}}if(nearest){if(nearest.type==='food'){player.hp=Math.min(player.maxhp,player.hp+45);popup(player.x,player.y-96,'+45 HEALTH','#d5ec69');}else{player.weapon=nearest.type;player.ammo=nearest.type==='gun'?24:nearest.type==='knife'?16:1;toast=`${nearest.type.toUpperCase()} EQUIPPED · J ATTACK`;toastTime=2;}drops.splice(drops.indexOf(nearest),1);sfx('pickup');score+=75;return;}if(player.weapon){shoot(player.x,player.y,player.dir,true,50,400);player.weapon=null;player.ammo=0;sfx('gun');}}
function bossMove(e){e.state='windup';e.timer=e.phase===2?.7:1; e.action=e.type==='truck'?'volley':e.type==='raptor'?'acid':e.type==='cinder'?'charge':e.type==='echo'?(Math.random()<.4?'summon':'pulse'):e.type==='regent'?(e.phase===2?'slam':'volley'):'punch';if(e.action==='charge'){e.targetY=player.y;e.dir=Math.sign(player.x-e.x)||-1;}if(['slam','pulse','acid'].includes(e.action)){zones.push({x:player.x,y:player.y,r:e.action==='slam'?110:75,t:e.timer,total:e.timer,friendly:false,damage:e.phase===2?28:18,air:e.action!=='acid'});} }
function executeBoss(e){if(e.action==='volley'){for(let j=-1;j<=1;j++){const dy=j*35;const dir=Math.sign(player.x-e.x)||-1;shoot(e.x+dir*40,e.y+dy,dir,false,18,310);}}if(e.action==='charge'){e.state='charge';e.timer=.72;e.vx=e.dir*480;return;}if(e.action==='punch'&&Math.abs(player.x-e.x)<110&&Math.abs(player.y-e.y)<45)damagePlayer(24,e.x);if(e.action==='summon'&&enemies.filter(v=>!v.dead&&!v.boss).length<4){spawnEnemy(e.x-95,e.y+30,'gunner');spawnEnemy(e.x+80,e.y-35,'raider');toast='ECHO IS CALLING REINFORCEMENTS';toastTime=2;}if(e.action==='slam'||e.action==='pulse'){shake=10;burst(e.x,e.y-50,'#d5ec69',18);}e.state='walk';e.timer=e.phase===2?.9:1.7;}
function updateEnemy(e,dt){e.anim+=dt;e.hurt=Math.max(0,e.hurt-dt);e.inv=Math.max(0,e.inv-dt);if(e.dead){e.dead-=dt;if(e.dead<=0)e.remove=true;return;}e.timer-=dt;if(e.state==='transform') {if(e.timer<=0)e.state='walk';return;}if(e.hurt>0)return;if(e.state==='hurt'){if(e.timer<=0){e.state='walk';e.timer=.8;}return;}if(e.state==='windup'){if(e.timer<=0){if(e.boss)executeBoss(e);else{if(e.type==='gunner'||e.type==='biker')shoot(e.x,e.y,e.dir,false,12,280);else if(Math.abs(e.x-player.x)<80&&Math.abs(e.y-player.y)<36)damagePlayer(e.type==='brute'?20:13,e.x);e.state='walk';e.timer=rand(1.3,2.5);}}return;}if(e.state==='charge'){e.x+=e.vx*dt;e.y=approach(e.y,e.targetY,160*dt);if(Math.abs(e.x-player.x)<92&&Math.abs(e.y-player.y)<45)damagePlayer(25,e.x-e.dir*50);if(e.timer<=0){e.state='walk';e.timer=1.3;}return;}
 e.dir=Math.sign(player.x-e.x)||e.dir;const distance=Math.abs(player.x-e.x),dy=Math.abs(player.y-e.y);let speed=e.boss?(e.phase===2?96:65):e.type==='brute'?62:e.type==='raptor'?125:95;speed*=difficulty==='arcade'?1.15:1;
 const range=e.type==='gunner'||e.type==='biker'?270:e.boss?110:57;if(distance>range-8)e.x+=e.dir*speed*dt;if(dy>9)e.y+=Math.sign(player.y-e.y)*speed*.52*dt;
 if(e.type==='gunner'&&distance<130)e.x-=e.dir*speed*.45*dt;
 if(e.timer<=0&&distance<range+20&&dy<(e.boss?150:35)){if(e.boss)bossMove(e);else{e.state='windup';e.timer=.45;}}
 for(const other of enemies)if(other!==e&&!other.dead&&Math.abs(other.x-e.x)<30&&Math.abs(other.y-e.y)<28){e.y+=Math.sign(e.y-other.y||e.id-other.id)*23*dt;}
 if(lock)e.x=clamp(e.x,lock.left+20,lock.right-35);e.y=clamp(e.y,GROUND+25,FLOOR-15);
}
function gamepad(){const pads=navigator.getGamepads?.()||[];const p=Array.from(pads).find(Boolean);if(!p){padKeys.clear();return;}const map=['KeyK','KeyE','KeyJ','KeyL'];for(let i=0;i<4;i++){if(p.buttons[i]?.pressed){if(!padKeys.has(map[i]))pressed.add(map[i]);padKeys.add(map[i]);}else padKeys.delete(map[i]);}for(const [key,on] of [['ArrowLeft',p.axes[0]<-.3||p.buttons[14]?.pressed],['ArrowRight',p.axes[0]>.3||p.buttons[15]?.pressed],['ArrowUp',p.axes[1]<-.3||p.buttons[12]?.pressed],['ArrowDown',p.axes[1]>.3||p.buttons[13]?.pressed]]){if(on)padKeys.add(key);else padKeys.delete(key);}if(p.buttons[9]?.pressed&&!gamepad.pauseHeld)pause();gamepad.pauseHeld=p.buttons[9]?.pressed;}
const down=(...ks)=>ks.some(k=>keys.has(k)||padKeys.has(k)),tap=(...ks)=>ks.some(k=>pressed.has(k));
function update(dt){time+=dt;music(dt);if(state!=='play'){pressed.clear();return;}gamepad();if(state!=='play')return;if(hitstop>0){hitstop-=dt;return;}stageTimer+=dt;runTime+=dt;const h=HEROES[selected];player.anim+=dt;player.inv=Math.max(0,player.inv-dt);player.hurt=Math.max(0,player.hurt-dt);player.attack=Math.max(0,player.attack-dt);player.special=Math.max(0,player.special-dt);player.specialCd=Math.max(0,player.specialCd-dt);player.boost=Math.max(0,player.boost-dt);player.boostCd=Math.max(0,player.boostCd-dt);
 let dx=(down('ArrowRight','KeyD')?1:0)-(down('ArrowLeft','KeyA')?1:0),dy=(down('ArrowDown','KeyS')?1:0)-(down('ArrowUp','KeyW')?1:0);player.run=down('ShiftLeft','ShiftRight');player.move=!!(dx||dy);if(dx)player.dir=dx;
 if(player.hurt<=0&&player.special<=0){const speed=level.drive?185:h.speed*(player.run?1.65:1);const drag=player.attack>0?.25:1;player.x+=(dx*speed*drag+(level.drive?100*(player.boost>0?2:1):0))*dt;player.y+=dy*speed*.68*dt;if(dx&&dy){player.x-=dx*speed*drag*dt*.25;player.y-=dy*speed*.68*dt*.25;}}
 player.x=clamp(player.x,lock?lock.left+30:camera+25,lock?lock.right-70:level.length+130);player.y=clamp(player.y,GROUND+30,FLOOR-14);
 if(player.z>0){player.vz-=850*dt;player.z+=player.vz*dt;if(player.z<=0){player.z=0;player.vz=0;burst(player.x,player.y,'#8b9470',4);}}
 if(down('KeyJ','KeyZ','Space'))attack();if(tap('KeyK','KeyX'))jump();if(tap('KeyL','KeyC'))special();if(tap('KeyE','KeyV'))pickup();
 for(const d of [...drops]){d.life-=dt;if(d.type==='food'&&Math.hypot(d.x-player.x,d.y-player.y)<30){player.hp=Math.min(player.maxhp,player.hp+45);popup(player.x,player.y-90,'+45 HEALTH','#d5ec69');drops.splice(drops.indexOf(d),1);sfx('pickup');}else if(d.life<=0)drops.splice(drops.indexOf(d),1);}
 for(const e of enemies)updateEnemy(e,dt);enemies=enemies.filter(e=>!e.remove);
 for(const b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.friendly){for(const e of enemies)if(!e.dead&&Math.abs(b.x-e.x)<(e.boss?65:26)&&Math.abs(b.y-e.y)<34){damageEnemy(e,b.damage,Math.sign(b.vx)*7);b.life=0;break;}}else if(Math.abs(b.x-player.x)<(level.drive?60:22)&&Math.abs(b.y-player.y)<25){damagePlayer(b.damage,b.x-Math.sign(b.vx)*35);b.life=0;}}
 bullets=bullets.filter(b=>b.life>0);
 for(const z of zones){z.t-=dt;if(z.t<=0){burst(z.x,z.y-20,z.friendly?'#efb36d':'#c7ea91',30);shake=8;if(z.friendly){for(const e of enemies)if(Math.hypot((e.x-z.x)*.8,e.y-z.y)<z.r)damageEnemy(e,z.damage,Math.sign(e.x-z.x)*35);}else if(Math.hypot((player.x-z.x)*.8,player.y-z.y)<z.r&&(!z.air||player.z<25))damagePlayer(z.damage,z.x,!z.air);}}
 zones=zones.filter(z=>z.t>0);
 for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=320*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);for(const f of floating){f.y-=30*dt;f.life-=dt;}floating=floating.filter(f=>f.life>0);
 if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0)combo=0;}toastTime=Math.max(0,toastTime-dt);shake=Math.max(0,shake-dt*22);flash=Math.max(0,flash-dt);
 const alive=enemies.filter(e=>!e.dead);if(lock&&alive.length===0&&enemies.length===0){lock=null;toast=bossSpawned?'PATH TO EDEN IS CLEAR':'GO →';toastTime=2.5;if(bossSpawned){stageClear();return;}drops.push({x:player.x+100,y:player.y,type:wave%2?'food':'bomb',life:60});score+=500;}
 if(!lock&&!bossSpawned&&wave<4&&player.x>350+wave*520)spawnWave(wave+1);if(!lock&&wave>=4&&!bossSpawned&&player.x>level.length-400)spawnBoss();
 const target=clamp(player.x-255,0,level.length-W+180);camera=approach(camera,target,500*dt);pressed.clear();
}
function rect(g,x,y,w,h,c){g.fillStyle=c;g.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function poly(g,pts,c){g.fillStyle=c;g.beginPath();pts.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.fill();}
function noise(n){return Math.abs(Math.sin(n*127.1+311.7)*43758.5453)%1;}
function tree(g,x,y,s=1,theme='jungle'){g.save();g.translate(Math.round(x),y);g.scale(s,s);rect(g,-9,-138,19,145,'#26382e');rect(g,1,-127,7,132,'#48543a');poly(g,[[-3,-130],[-36,-183],[-20,-188],[10,-125]],'#344537');const colors=theme==='harbor'?['#315e42','#497c4b','#6c8e53']:['#274a35','#3b6140','#577444','#6f8a50'];for(let k=0;k<30;k++){const xx=(noise(k+x)-.5)*135,yy=-130-noise(k*8+x)*70;rect(g,xx,yy,24+noise(k+4)*25,10+noise(k+7)*18,colors[k%4]);}for(let k=0;k<6;k++)rect(g,-3+k*2,-185+k*12,3,11,'#6c8447');g.restore();}
function building(g,x,y,w,h,seed=1){rect(g,x,y-h,w,h,'#334a48');rect(g,x+5,y-h+3,w-9,h-3,'#425b54');rect(g,x+w-15,y-h+3,14,h,'#2c403d');for(let yy=y-h+12;yy<y-8;yy+=17)for(let xx=x+9;xx<x+w-18;xx+=17){rect(g,xx,yy,8,11,noise(xx+yy+seed)>.7?'#8e9d71':'#243e3d');rect(g,xx,yy,8,2,'#607c69');}for(let j=0;j<7;j++){const xx=x+noise(j+seed)*w;rect(g,xx,y-h+noise(j+8)*h,4,30,'#607847');}poly(g,[[x,y-h],[x+12,y-h-8],[x+w-9,y-h-8],[x+w,y-h]],'#62766a');}
